const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let doc=null,view='home',panel='templates',chosen=new Set(),zoom=.5,history=new History(),drag=null,clipboard=[],assets=[],brand={id:'brand',name:'Meine Marke',colors:['#7554e8','#252638','#eee8df'],font:'Arial'},homeFilter='all',homeQuery='',templateFilter='Alle',templateQuery='',drawMode=false,drawColor='#7554e8',drawSize=8,snap=true,saveTimer,saveQueue=Promise.resolve(),dirty=false,presentation=null,abortVideo=null;
let remoteNotice=null,editGeneration=0,ownTemplates=[],gradientTarget=null,replaceTarget=null;
const fontOptions=()=>[...fonts.map(f=>({family:f,label:f})),...(doc?.fonts||[]).map(f=>({family:fontFamily(f),label:f.label}))];
const readOnly=()=>doc?.cloud?.role==='viewer';
const current=()=>doc.pages[doc.page],selection=()=>current().elements.filter(e=>chosen.has(e.id)),first=()=>selection()[0];
const button=(action,label,extra='')=>`<button data-action="${action}" ${extra}>${label}</button>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function modal(title,content,wide=false){$('#modal').classList.toggle('large',wide);$('#modalBody').innerHTML=`<div class="dialog-head"><h2>${title}</h2>${button('close','✕','aria-label="Dialog schließen"')}</div>${content}`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;$('#modal [data-action=close]')?.focus({preventScroll:true})}
function status(text){if($('#saved'))$('#saved').textContent=text}
function queueSave(){editGeneration++;dirty=true;if(doc.cloud&&!readOnly())doc.cloud.pending=true;status('Wird gespeichert …');clearTimeout(saveTimer);saveTimer=setTimeout(()=>flushSave(),450)}
async function flushSave(){
  clearTimeout(saveTimer);if(!doc||!dirty)return saveQueue;
  const snapshot=clone(doc),generation=editGeneration;snapshot.updated=Date.now();doc.updated=snapshot.updated;dirty=false;
  saveQueue=saveQueue.catch(()=>{}).then(async()=>{
    await db.put('projects',snapshot);
    let online=false;
    if(doc?.id===snapshot.id&&doc.cloud?.conflict&&snapshot.cloud)snapshot.cloud.conflict=true;
    if(snapshot.cloud?.pending&&!snapshot.cloud.conflict&&cloud.user?.id===snapshot.cloud.userId&&snapshot.cloud.origin===location.origin&&snapshot.cloud.role!=='viewer'){
      try{
        const saved=await cloud.save(snapshot);
        snapshot.cloud={...snapshot.cloud,revision:saved.revision,role:saved.role,pending:false};
        await db.put('projects',snapshot);online=true;
        if(doc?.id===snapshot.id){doc.cloud={...snapshot.cloud,pending:editGeneration!==generation};remoteNotice=null;}
      }catch(error){
        snapshot.cloud.conflict=error.status===409;
        snapshot.cloud.pending=true;
        if(doc?.id===snapshot.id)doc.cloud={...snapshot.cloud};
        await db.put('projects',snapshot);
        if(error.status===409)toast('Online-Konflikt: Deine Änderungen sind lokal gesichert. Öffne „Teilen & Sync“.');
        else if(error.status===403||error.status===404){if(doc?.id===snapshot.id)doc.cloud.conflict=true;toast('Online-Zugriff geändert. Lokale Änderungen wurden gesichert.');}
        else if(error.status===401)toast('Bitte erneut anmelden. Dein Projekt ist lokal gesichert.');
      }
    }
    if(doc?.id===snapshot.id&&!dirty)status(online?'✓ Lokal und online gespeichert':snapshot.cloud?.pending?'✓ Lokal gespeichert · Online-Sync ausstehend':'✓ Auf diesem Gerät gespeichert');
  }).catch(error=>{dirty=true;status('Speichern fehlgeschlagen');toast('Speicherfehler: Bitte dein Projekt als Datei sichern.');console.error(error)});
  return saveQueue;
}
function change(fn){if(readOnly())return toast('Dieses Online-Projekt ist schreibgeschützt. Erstelle eine lokale Kopie zum Bearbeiten.');history.push(doc);fn();doc.updated=Date.now();renderEditor();queueSave()}
function normalizeText(e){if(e.type==='text')e.h=e.curve?curveGeometry(e).height:Math.max(e.size*1.15,textLines(e).length*e.size*(e.lineHeight||1.16)+e.size*.15)}
function add(...els){change(()=>{current().elements.push(...els);chosen=new Set(els.map(e=>e.id));els.forEach(normalizeText)})}
function applyTemplate(index){const t=templates[index],els=t.els(),sx=doc.width/1080,sy=doc.height/1080;change(()=>{current().bg=t.bg;current().gradient=null;current().elements=els.map(e=>{e.x*=sx;e.y*=sy;e.w*=sx;e.h*=sy;if(e.size){e.size*=Math.min(sx,sy);e.font=e.font==='Manrope'?'Arial':e.font;normalizeText(e)}return e});chosen.clear()});toast('Vorlage angewendet. Strg+Z macht die Änderung rückgängig.')}
function cloudLink(result){return {id:result.id,revision:result.revision,role:result.role,userId:cloud.user.id,origin:location.origin,pending:false,conflict:false}}
function watchRemote(){
  cloud.stop();
  if(!doc?.cloud||!cloud.user||doc.cloud.origin!==location.origin||doc.cloud.userId!==cloud.user.id)return;
  const id=doc.cloud.id;
  cloud.watch(id,async message=>{
    if(doc?.cloud?.id!==id||message.revision<=doc.cloud.revision)return;
    if(dirty||drag||cloud.saving||doc.cloud.pending){remoteNotice=message;status('Online-Änderung verfügbar · eigene Arbeit lokal gesichert');return;}
    try{
      const incoming=await cloud.open(id);
      if(doc?.cloud?.id!==id||dirty||drag||doc.cloud.pending){remoteNotice=message;return;}
      const localId=doc.id,pageIndex=doc.page;
      await loadFontAssets(incoming.doc.fonts||[]);doc=incoming.doc;doc.id=localId;doc.cloud=cloudLink(incoming);doc.page=Math.min(pageIndex,doc.pages.length-1);
      history.clear();chosen.clear();await db.put('projects',doc);renderEditor();status('✓ Online-Änderung übernommen');
    }catch(error){toast(error.message)}
  },reason=>{if(doc?.cloud?.id!==id)return;if(reason==='session'){cloud.user=null;cloud.csrf=null;status('Sitzung abgelaufen · lokal weiterarbeiten');toast('Bitte erneut anmelden. Dein lokaler Stand bleibt erhalten.');return}doc.cloud.conflict=true;doc.cloud.role='viewer';renderEditor();toast('Der Online-Zugriff wurde beendet. Die lokale Ansicht bleibt erhalten.')});
}
async function openRemote(id){
  await flushSave();
  if(doc?.cloud?.id===id&&doc.cloud.pending){const backup=clone(doc);backup.id=uid();backup.title+=' · Konfliktkopie';delete backup.cloud;await db.put('projects',backup);toast('Ausstehende Änderungen sind als lokale Konfliktkopie gesichert.');}
  const incoming=await cloud.open(id);
  await loadFontAssets(incoming.doc.fonts||[]);doc=incoming.doc;doc.cloud=cloudLink(incoming);history.clear();chosen.clear();remoteNotice=null;
  await db.put('projects',doc);$('#modal').close();editorShell();fit();watchRemote();
}
async function cloudDialog(sharing=false){
  if(!cloud.available){
    modal('Konto & gemeinsame Projekte',`<p class="sub">Diese Adresse liefert den lokalen Editor aus. Für Konten und gemeinsame Projekte starte den beiliegenden Server:</p><pre class="code-box">npm run cloud</pre><p class="sub">Danach <strong>http://127.0.0.1:4174/</strong> öffnen. Auf einem eigenen Server funktioniert dieselbe Anwendung mit mehreren Nutzern.</p><div class="panel-note">GitHub Pages führt keinen Node-Server aus. Es kann weiterhin die lokale Editor-Version bereitstellen. Die Server-Anleitung im Repository erklärt den getrennten Betrieb.</div>`);return;
  }
  if(!cloud.user){accountUI.showLogin();return;}
  if(sharing&&view==='editor')await flushSave();
  const projects=(await cloud.list()).projects.sort((a,b)=>b.updated-a.updated);
  let projectSection='';
  if(sharing&&view==='editor'){
    if(!doc.cloud)projectSection=`<section class="cloud-section"><h3>Dieses Design ist lokal</h3><p class="sub">Speichere eine Online-Kopie, um es auf diesem Server zu teilen. Danach werden Änderungen automatisch lokal und online gespeichert.</p>${button('cloudPublish','Online-Kopie speichern','class="primary wide"')}</section>`;
    else{
      const l=doc.cloud,isOwner=l.role==='owner';
      let people=[],links=[];
      if(isOwner&&l.userId===cloud.user.id){people=(await cloud.members(l.id)).members;links=(await cloud.invites(l.id)).invites;}
      projectSection=`<section class="cloud-section"><h3>${esc(doc.title)}</h3><p class="sub">Version ${l.revision} · ${l.role==='owner'?'Eigentümer':l.role==='editor'?'Bearbeitungsrechte':'Leserechte'}${l.pending?' · Änderungen nur lokal':''}</p>${l.conflict||remoteNotice?'<div class="sync-warning">Ein anderer Stand ist verfügbar oder der Zugriff hat sich geändert. Beim Neuladen werden ausstehende Änderungen zuerst als lokale Konfliktkopie gesichert.</div>':''}<div class="row">${l.pending&&!l.conflict?button('cloudSync','Jetzt synchronisieren'):''}${button('cloudRefresh','Online-Stand laden')}${button('cloudCopy','Lokale Kopie')}</div>${isOwner?`<div class="separator"></div><h3>Einladung erstellen</h3><label for="inviteRole">Berechtigung</label><select id="inviteRole"><option value="viewer">Nur ansehen</option><option value="editor">Bearbeiten</option></select>${button('cloudInvite','Einladungslink erstellen','class="primary wide" style="margin-top:12px"')}<div id="newInvite"></div><p class="sub">Link sieben Tage gültig. Empfänger benötigen ein Konto auf diesem Server. Wer den Link besitzt, kann die gewählten Rechte erhalten.</p><h3>Mitglieder</h3>${people.map(p=>`<div class="project-item"><span>${esc(p.name)}<small>${p.role==='owner'?'Eigentümer':p.role==='editor'?'Bearbeiten':'Ansehen'}</small></span>${p.role!=='owner'?`<button data-remove-member="${p.id}">Entfernen</button>`:''}</div>`).join('')}<h3 style="margin-top:20px">Aktive Einladungen</h3>${links.map(i=>`<div class="project-item"><span>${i.role==='editor'?'Bearbeiten':'Ansehen'}<small>Bis ${new Date(i.expires).toLocaleDateString('de-DE')}</small></span><button data-revoke-invite="${i.id}">Widerrufen</button></div>`).join('')||'<p class="sub">Keine aktiven Links.</p>'}`:''}</section>`;
    }
  }
  const token=location.hash.startsWith('#invite=')?location.hash.slice(8):'';
  modal(sharing?'Teilen & Synchronisieren':'Dein Online-Studio',`<div class="cloud-account"><span class="avatar">${esc(cloud.user.name[0]?.toUpperCase())}</span><div><strong>${esc(cloud.user.name)}</strong><small>${esc(cloud.user.email)}</small></div>${button('accountSettings','Kontoeinstellungen')}${button('cloudLogout','Abmelden')}</div>${token?`<div class="panel-note">Ein Einladungslink wartet auf dich.${button('cloudRedeem','Einladung annehmen','class="primary wide" style="margin-top:12px"')}</div>`:''}${projectSection}<div class="separator"></div><h3>Online-Projekte</h3><div class="cloud-projects">${projects.map(p=>`<div class="project-item"><span>${esc(p.title)}<small>${p.pages} Seite(n) · Version ${p.revision} · ${p.role==='viewer'?'Ansehen':'Bearbeiten'}</small></span><button data-cloud-open="${p.id}">Öffnen</button></div>`).join('')||'<p class="sub">Noch keine Online-Projekte. Öffne ein lokales Design und wähle „Teilen“.</p>'}</div>`,true);
}
async function cloudAction(a){
  if(a==='cloud'||a==='cloudShare')return cloudDialog(a==='cloudShare');
  if(a==='cloudLogout'){await flushSave();await cloud.logout();doc=null;chosen.clear();await home();await cloudDialog();return;}
  if(a==='cloudPublish'){
    await flushSave();const online=await cloud.create(doc);doc.cloud=cloudLink(online);
    await db.put('projects',doc);renderEditor();watchRemote();await cloudDialog(true);toast('Online-Kopie erstellt. Weitere Änderungen werden synchronisiert.');return;
  }
  if(a==='cloudSync'){dirty=true;await flushSave();await cloudDialog(true);return;}
  if(a==='cloudRefresh'){await openRemote(doc.cloud.id);return;}
  if(a==='cloudCopy'){
    await flushSave();cloud.stop();doc=clone(doc);doc.id=uid();doc.title+=' · Lokale Kopie';delete doc.cloud;
    history.clear();chosen.clear();dirty=true;await flushSave();$('#modal').close();editorShell();fit();return;
  }
  if(a==='cloudInvite'){
    const invitation=await cloud.invite(doc.cloud.id,$('#inviteRole').value);
    const link=new URL(location.pathname,location.origin);link.hash='invite='+invitation.token;
    $('#newInvite').innerHTML=`<label for="inviteLink">Einladungslink (zum Kopieren auswählen)</label><input id="inviteLink" readonly value="${esc(link.href)}"><p class="sub">Der vollständige Link wird nur jetzt angezeigt. Er ist unter „Aktive Einladungen“ widerrufbar.</p>`;$('#inviteLink').focus();$('#inviteLink').select();return;
  }
  if(a==='cloudRedeem'){
    const token=location.hash.slice(8),result=await cloud.redeem(token);window.history.replaceState(null,'',location.pathname+location.search);await openRemote(result.id);toast('Einladung angenommen.');
  }
}
