async function home(){await flushSave();cloud.stop();view='home';let projects=(await db.all('projects')).filter(p=>!p.cloud||p.cloud.userId===cloud.user?.id).sort((a,b)=>b.updated-a.updated);const folders=[...new Set(projects.filter(p=>!p.deleted&&p.folder).map(p=>p.folder))];projects=projects.filter(p=>homeFilter==='trash'?p.deleted:!p.deleted).filter(p=>homeFilter==='favorites'?p.favorite:homeFilter.startsWith('folder:')?p.folder===homeFilter.slice(7):true).filter(p=>p.title.toLowerCase().includes(homeQuery.toLowerCase()));
$('#app').innerHTML=`<div class="dashboard"><aside class="home-nav"><a class="brand" href="#" data-action="home">${logo()}</a><div class="profile"><span class="avatar">S</span><div>Dein kreativer Raum<small>Lokal · auf diesem Gerät</small></div></div>${button('new','＋ Design erstellen','class="primary wide"')}<div class="home-links">${[['all','⌂','Übersicht'],['favorites','☆','Favoriten'],['trash','♲','Papierkorb']].map(([f,i,n])=>`<button data-home-filter="${f}" class="${homeFilter===f?'active':''}">${i} &nbsp; ${n}</button>`).join('')}${button('brand','◈ &nbsp; Meine Marke')}${button('import','⇧ &nbsp; Projekt importieren')}${button('cloud',cloud.user?'☁ &nbsp; '+esc(cloud.user.name):'☁ &nbsp; Konto & Online')}</div><div class="separator"></div><h3>ORDNER</h3>${folders.map(f=>`<button class="folder-link" data-home-filter="folder:${esc(f)}">▱ &nbsp; ${esc(f)}</button>`).join('')||'<p class="sub">Ordne Projekte über ihr Menü einem Ordner zu.</p>'}<div class="home-bottom">Open Source · MIT<br>Ohne Premium-Sperren.<br>${button('help','Hilfe & Tastenkürzel')}</div></aside><section class="home-content"><div class="home-top"><span>Dein Studio. Deine Ideen.</span><input id="projectSearch" placeholder="⌕ Projekte suchen" aria-label="Projekte suchen" value="${esc(homeQuery)}">${button('commands','⌕','aria-label="Befehle suchen"')}${button('help','?','aria-label="Hilfe"')}${button('homeMenu','☰','class="mobile-menu" aria-label="Navigation"')}</div>${homeFilter==='all'&&!homeQuery?`<div class="hero"><div class="hero-copy"><span class="eyebrow">GROSSE IDEEN BEGINNEN HIER</span><h1>Was möchtest du<br>heute gestalten?</h1><p>Vom ersten Gedanken bis zum fertigen Design.<br>Mach etwas, das nach dir aussieht.</p>${button('new','Lass uns anfangen ↗','class="hero-button"')}</div><div class="hero-art" aria-hidden="true"><div class="art-card one">MAKE<br><i>something.</i><span>✦</span></div><div class="art-card two">a little<br><b>MAGIC.</b><span>↗</span></div></div></div><div class="format-list">${formats.slice(0,6).map(([name,w,h,icon],i)=>`<button data-format="${i}"><b style="--tone:${['#e8dfff','#fce1e9','#dcefe6','#ffebd5','#dce9ff','#f1e6ff'][i]}">${icon}</b><span>${name}</span></button>`).join('')}</div>`:''}<div class="section-head"><div><h2>${homeFilter==='trash'?'Papierkorb':homeFilter==='favorites'?'Deine Favoriten':homeFilter.startsWith('folder:')?esc(homeFilter.slice(7)):'Deine Designs'}</h2><p class="sub">${homeFilter==='trash'?'Gelöschte Projekte können wiederhergestellt werden.':'Gespeichert auf diesem Gerät · jederzeit weitergestalten'}</p></div><span class="badge">${projects.length} PROJEKTE</span></div><div class="project-grid">${projects.map(p=>`<article class="project-card"><button class="project-cover" data-open="${p.id}" ${p.deleted?'disabled':''}>${svgMarkup(p.pages[0],p.width,p.height,{fonts:p.fonts||[]})}</button><div class="project-caption"><div><strong>${esc(p.title)}</strong><small>${p.pages.length} Seite${p.pages.length!==1?'n':''} · ${new Date(p.updated).toLocaleDateString('de-DE')}</small></div><button data-project-menu="${p.id}" aria-label="Menü für ${esc(p.title)}">•••</button></div></article>`).join('')||`<div class="empty-projects"><div>✧</div><h2>${homeQuery?'Noch kein Treffer.':'Platz für deine nächste Idee.'}</h2><p class="sub">${homeQuery?'Versuche einen anderen Projektnamen.':'Starte mit einem Format oder einer Vorlage.'}</p>${button('new','＋ Design erstellen','class="primary"')}</div>`}</div>${homeFilter==='all'&&!homeQuery?`<div class="section-head"><h2>Ein bisschen Inspiration</h2><span class="sub">Eigene Vorlagen · vollständig editierbar</span></div><div class="inspiration-grid">${templates.map((t,i)=>`<button class="inspiration-card" data-home-template="${i}">${svgMarkup({bg:t.bg,elements:t.els()},1080,1080)}<strong>${esc(t.name)}</strong><small>${t.category}</small></button>`).join('')}</div>`:''}</section></div>`;$('#projectSearch').oninput=e=>{const pos=e.target.selectionStart;homeQuery=e.target.value;home().then(()=>{$('#projectSearch').focus();$('#projectSearch').setSelectionRange(pos,pos)})}}
async function openProject(id){await flushSave();const p=await db.get('projects',id);if(!p||p.deleted)return toast('Projekt nicht gefunden.');if(p.cloud&&p.cloud.userId!==cloud.user?.id)return toast('Für dieses Online-Projekt bitte zuerst mit dem passenden Konto anmelden.');await loadFontAssets(p.fonts||[]);doc=p;history.clear();chosen.clear();editorShell();fit();watchRemote()}
