if(a==='applyGradient'||a==='clearGradient'){const target=gradientTarget;if(!target||target.locked)throw Error('Die Auswahl ist nicht mehr verfügbar.');const angle=+$('#gradientAngle').value;if(!Number.isFinite(angle)||angle < -360||angle>360)throw Error('Bitte einen Winkel von −360 bis 360 eingeben.');change(()=>target.gradient=a==='clearGradient'?null:{type:$('#gradientType').value,from:$('#gradientFrom').value,to:$('#gradientTo').value,angle});$('#modal').close()}
