if(a==='applyBrand')change(()=>{current().bg=brand.colors[2]||'#ffffff';current().gradient=null;current().elements.filter(e=>!e.locked&&e.type!=='image').forEach(e=>{e.gradient=null;e.fill=e.type==='text'?brand.colors[1]:brand.colors[0];if(e.type==='text'){e.font=brand.font;normalizeText(e)}if(e.type==='chart')e.palette=brand.colors;if(e.type==='table')e.headerColor=brand.colors[0]})});
